          note: { ko: "출처 1곳(ゲーム攻略マン).", en: "Single source (Game Kouryakuman)." },
          puzzles: [
            { title: { ko: "High Jump", en: "High Jump" }, note: { ko: "클리어 3,000점 이상. 해금: 처음부터. 클리어 보너스 +1,000pt. TownGo: 5,000점 이상 → 30Sp.", en: "Clear at 3,000+. Unlock: from the start. Clear bonus +1,000pt. TownGo: 5,000+ → 30 Sp." } },
            { title: { ko: "Access to Bank", en: "Access to Bank" }, note: { ko: "클리어 3,000점 이상. 해금: 처음부터. 클리어 보너스 +1,500pt. TownGo: 6,000점 이상 → 30Sp.", en: "Clear at 3,000+. Unlock: from the start. Clear bonus +1,500pt. TownGo: 6,000+ → 30 Sp." } },
            { title: { ko: "Make Rail Trick", en: "Make Rail Trick" }, note: { ko: "클리어 4,000점 이상. 해금: 스토리 미션 「미쓰이의 스코어를 넘어라」 후. 클리어 보너스 +2,000pt. TownGo: 7,000점 이상 → 30Sp.", en: "Clear at 4,000+. Unlock: after the story mission to beat Mitsui's score. Clear bonus +2,000pt. TownGo: 7,000+ → 30 Sp." } },
            { title: { ko: "Combo Park", en: "Combo Park" }, note: { ko: "클리어 4,000점 이상. 해금: 스토리 미션 「시키시마의 스코어를 넘어라」 후. 클리어 보너스 +2,500pt. TownGo: 8,000점 이상 → 100Sp.", en: "Clear at 4,000+. Unlock: after the story mission to beat Shikishima's score. Clear bonus +2,500pt. TownGo: 8,000+ → 100 Sp." } },
            { title: { ko: "Section Jam", en: "Section Jam" }, note: { ko: "클리어 5,000점 이상. 해금: 스토리 미션 「시키시마의 스코어를 넘어라」 후. 클리어 보너스 +3,500pt. TownGo: 10,000점 이상 → 100Sp.", en: "Clear at 5,000+. Unlock: after the story mission to beat Shikishima's score. Clear bonus +3,500pt. TownGo: 10,000+ → 100 Sp." } },
            { title: { ko: "Outside slalom Park", en: "Outside slalom Park" }, note: { ko: "클리어 6,000점 이상. 해금: 처음부터. 클리어 보너스 +1,000pt.", en: "Clear at 6,000+. Unlock: from the start. Clear bonus +1,000pt." } },
            { title: { ko: "Make High Jump", en: "Make High Jump" }, note: { ko: "클리어 6,000점 이상. 해금: 처음부터. 클리어 보너스 +1,500pt.", en: "Clear at 6,000+. Unlock: from the start. Clear bonus +1,500pt." } },
            { title: { ko: "Special Open Air", en: "Special Open Air" }, note: { ko: "클리어 6,000점 이상. 해금: DLC 「탐정 라이프 충실 팩」. 클리어 보너스 +2,000pt.", en: "Clear at 6,000+. Unlock: DLC (Detective Life Pack). Clear bonus +2,000pt." } },
          ],
